const headers = $input.first().json.headers || {};
const token = headers['x-pmo-token'] || headers['X-PMO-Token'] || 'change-me-pmo-secret-2026';
let context = '';
if ($input.first().json.body) {
  const body = $input.first().json.body;
  context = body.context || body.prompt || '';
}
const payload = context ? { context } : {};
const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://lmstudio-gateway:8081/api/pmo/risk/run',
  headers: {
    'X-PMO-Token': token,
    'Content-Type': 'application/json',
  },
  body: payload,
  json: true,
  timeout: 900000,
});
return [{ json: response }];
